files.patch:
@@ -1,1030 +0,0 @@
-<title>Hachi — the evaluation opening, seam by seam</title>
-<style>
-  :root {
-    --paper:#F2F3F8; --surface:#FFFFFF; --surface-2:#EBEDF4; --surface-3:#E3E6F0;
-    --ink:#171A24; --ink-soft:#3E4356; --muted:#6A7089;
-    --line:#DBDEEA; --line-soft:#E7E9F3;
-    --accent:#4B57C9; --accent-2:#6470E0; --accent-ghost:rgba(75,87,201,.10); --on-accent:#FFFFFF;
-    --ok:#0E9F86; --ok-ghost:rgba(14,159,134,.12);
-    --warn:#B7790A; --warn-ghost:rgba(183,121,10,.13);
-    --bad:#D0435A; --bad-ghost:rgba(208,67,90,.12);
-    --plan:#7A8099; --plan-ghost:rgba(122,128,153,.12);
-    --rep:#2D6FA8; --rep-ghost:rgba(45,111,168,.12);
-    --shadow:0 1px 2px rgba(20,26,45,.05), 0 6px 20px -12px rgba(20,26,45,.18);
-    --font-sans:"SF Pro Text","SF Pro Display",-apple-system,BlinkMacSystemFont,"Segoe UI","Helvetica Neue",Arial,sans-serif;
-    --font-mono:"SF Mono","JetBrains Mono","Berkeley Mono",ui-monospace,"Cascadia Code",Menlo,Consolas,monospace;
-    --maxw:1080px;
-  }
-  @media (prefers-color-scheme: dark) {
-    :root {
-      --paper:#0E1017; --surface:#171A24; --surface-2:#1E2230; --surface-3:#252A3B;
-      --ink:#E7E9F2; --ink-soft:#B7BCCF; --muted:#818799;
-      --line:#282D3D; --line-soft:#20242F;
-      --accent:#8A96F2; --accent-2:#A0AAFB; --accent-ghost:rgba(138,150,242,.13); --on-accent:#0E1017;
-      --ok:#34D9BC; --ok-ghost:rgba(52,217,188,.13);
-      --warn:#EEB13B; --warn-ghost:rgba(238,177,59,.14);
-      --bad:#F2708A; --bad-ghost:rgba(242,112,138,.14);
-      --plan:#8B90A6; --plan-ghost:rgba(139,144,166,.13);
-      --rep:#68B0E3; --rep-ghost:rgba(104,176,227,.14);
-      --shadow:0 1px 2px rgba(0,0,0,.3), 0 10px 30px -16px rgba(0,0,0,.6);
-    }
-  }
-  :root[data-theme="light"] {
-    --paper:#F2F3F8; --surface:#FFFFFF; --surface-2:#EBEDF4; --surface-3:#E3E6F0;
-    --ink:#171A24; --ink-soft:#3E4356; --muted:#6A7089;
-    --line:#DBDEEA; --line-soft:#E7E9F3;
-    --accent:#4B57C9; --accent-2:#6470E0; --accent-ghost:rgba(75,87,201,.10); --on-accent:#FFFFFF;
-    --ok:#0E9F86; --ok-ghost:rgba(14,159,134,.12);
-    --warn:#B7790A; --warn-ghost:rgba(183,121,10,.13);
-    --bad:#D0435A; --bad-ghost:rgba(208,67,90,.12);
-    --plan:#7A8099; --plan-ghost:rgba(122,128,153,.12);
-    --rep:#2D6FA8; --rep-ghost:rgba(45,111,168,.12);
-    --shadow:0 1px 2px rgba(20,26,45,.05), 0 6px 20px -12px rgba(20,26,45,.18);
-  }
-  :root[data-theme="dark"] {
-    --paper:#0E1017; --surface:#171A24; --surface-2:#1E2230; --surface-3:#252A3B;
-    --ink:#E7E9F2; --ink-soft:#B7BCCF; --muted:#818799;
-    --line:#282D3D; --line-soft:#20242F;
-    --accent:#8A96F2; --accent-2:#A0AAFB; --accent-ghost:rgba(138,150,242,.13); --on-accent:#0E1017;
-    --ok:#34D9BC; --ok-ghost:rgba(52,217,188,.13);
-    --warn:#EEB13B; --warn-ghost:rgba(238,177,59,.14);
-    --bad:#F2708A; --bad-ghost:rgba(242,112,138,.14);
-    --plan:#8B90A6; --plan-ghost:rgba(139,144,166,.13);
-    --rep:#68B0E3; --rep-ghost:rgba(104,176,227,.14);
-    --shadow:0 1px 2px rgba(0,0,0,.3), 0 10px 30px -16px rgba(0,0,0,.6);
-  }
-
-  * { box-sizing:border-box; }
-  html { -webkit-text-size-adjust:100%; }
-  body {
-    margin:0; background:var(--paper); color:var(--ink);
-    font-family:var(--font-sans); font-size:16px; line-height:1.6;
-    -webkit-font-smoothing:antialiased; text-rendering:optimizeLegibility;
-    overflow-x:hidden;
-  }
-  .wrap { max-width:var(--maxw); margin:0 auto; padding:0 24px; }
-  a { color:var(--accent); text-decoration:none; }
-  a:hover { text-decoration:underline; }
-  :focus-visible { outline:2px solid var(--accent); outline-offset:2px; border-radius:4px; }
-
-  code, .mono { font-family:var(--font-mono); font-variant-ligatures:none; }
-  .num { font-variant-numeric:tabular-nums; }
-
-  /* ---------- eyebrow / labels ---------- */
-  .eyebrow {
-    font-family:var(--font-mono); font-size:11.5px; letter-spacing:.16em;
-    text-transform:uppercase; color:var(--muted); font-weight:600;
-  }
-
-  /* ---------- hero ---------- */
-  header.hero { position:relative; padding:76px 0 40px; overflow:hidden; }
-  .hero-mark {
-    position:absolute; right:-4%; top:-8%; font-size:min(46vw,440px); line-height:1;
-    font-weight:800; color:var(--accent); opacity:.06; user-select:none; pointer-events:none;
-    font-family:"Hiragino Sans","Yu Gothic",var(--font-sans);
-  }
-  .hero-kicker { display:flex; align-items:center; gap:12px; margin-bottom:26px; }
-  .hero-kicker .glyph {
-    font-family:"Hiragino Sans","Yu Gothic",var(--font-sans); font-weight:700;
-    font-size:22px; color:var(--accent); line-height:1;
-    width:38px; height:38px; display:grid; place-items:center;
-    border:1.5px solid var(--accent); border-radius:9px; background:var(--accent-ghost);
-  }
-  h1 {
-    font-size:clamp(38px,6.4vw,66px); line-height:1.02; letter-spacing:-.028em;
-    font-weight:800; margin:0 0 8px; text-wrap:balance; max-width:16ch;
-  }
-  .hero-sub {
-    font-size:clamp(16px,2.1vw,20px); color:var(--ink-soft); max-width:60ch;
-    margin:14px 0 0; line-height:1.5; font-weight:400;
-  }
-  .hero-sub strong { color:var(--ink); font-weight:600; }
-  .hero-meta {
-    margin-top:26px; display:flex; flex-wrap:wrap; gap:8px 10px; align-items:center;
-    font-family:var(--font-mono); font-size:12.5px; color:var(--muted);
-  }
-  .hero-meta .chip {
-    border:1px solid var(--line); background:var(--surface); border-radius:999px;
-    padding:4px 11px; color:var(--ink-soft);
-  }
-
-  /* ---------- section scaffolding ---------- */
-  section { padding:44px 0; }
-  .sec-head { margin-bottom:26px; }
-  .sec-head h2 {
-    font-size:clamp(22px,3vw,29px); letter-spacing:-.02em; font-weight:750;
-    margin:8px 0 0; text-wrap:balance;
-  }
-  .sec-head p { color:var(--ink-soft); margin:10px 0 0; max-width:70ch; }
-  .rule { height:1px; background:var(--line); border:0; margin:0; }
-
-  /* ---------- summary tiles ---------- */
-  .tiles { display:grid; grid-template-columns:repeat(auto-fit,minmax(212px,1fr)); gap:14px; }
-  .tile {
-    background:var(--surface); border:1px solid var(--line); border-radius:14px;
-    padding:18px 18px 16px; position:relative; box-shadow:var(--shadow);
-  }
-  .tile .cap { display:flex; align-items:center; gap:8px; }
-  .tile .dot { width:9px; height:9px; border-radius:50%; flex:none; }
-  .tile .n { font-size:38px; font-weight:800; letter-spacing:-.03em; margin:6px 0 0; line-height:1; }
-  .tile .lbl { font-family:var(--font-mono); font-size:11px; letter-spacing:.12em; text-transform:uppercase; color:var(--muted); font-weight:600; }
-  .tile .sub { color:var(--ink-soft); font-size:13px; margin-top:9px; line-height:1.4; }
-  .tile.ok .n{color:var(--ok);} .tile.ok .dot{background:var(--ok);}
-  .tile.warn .n{color:var(--warn);} .tile.warn .dot{background:var(--warn);}
-  .tile.bad .n{color:var(--bad);} .tile.bad .dot{background:var(--bad);}
-  .tile.plan .n{color:var(--plan);} .tile.plan .dot{background:var(--plan);}
-  .tile.rep .n{color:var(--rep);} .tile.rep .dot{background:var(--rep);}
-
-  .barwrap { margin-top:20px; }
-  .bar { display:flex; height:12px; border-radius:999px; overflow:hidden; border:1px solid var(--line); background:var(--surface-2); }
-  .bar > span { display:block; height:100%; }
-  .bar-legend { display:flex; flex-wrap:wrap; gap:6px 18px; margin-top:12px; font-size:12.5px; color:var(--ink-soft); }
-  .bar-legend .k { display:inline-flex; align-items:center; gap:7px; }
-  .bar-legend .sw { width:11px; height:11px; border-radius:3px; }
-
-  /* ---------- legend / how-to-read ---------- */
-  .howto {
-    display:grid; grid-template-columns:1.15fr 1fr; gap:24px; align-items:start;
-  }
-  .legend-card {
-    background:var(--surface); border:1px solid var(--line); border-radius:14px; padding:20px 22px;
-    box-shadow:var(--shadow);
-  }
-  .legend-card h3 { font-size:13px; font-family:var(--font-mono); letter-spacing:.1em; text-transform:uppercase; color:var(--muted); margin:0 0 14px; font-weight:600; }
-  .legend-row { display:flex; align-items:flex-start; gap:12px; padding:9px 0; border-top:1px solid var(--line-soft); }
-  .legend-row:first-of-type { border-top:0; }
-  .legend-row .key { flex:none; margin-top:2px; }
-  .legend-row .txt { font-size:13.5px; color:var(--ink-soft); line-height:1.45; }
-  .legend-row .txt b { color:var(--ink); font-weight:600; }
-
-  /* status pill */
-  .pill {
-    display:inline-flex; align-items:center; gap:6px; font-family:var(--font-mono);
-    font-size:11px; font-weight:600; letter-spacing:.04em; text-transform:uppercase;
-    padding:3px 9px; border-radius:999px; white-space:nowrap; border:1px solid transparent;
-  }
-  .pill::before{ content:""; width:7px; height:7px; border-radius:50%; background:currentColor; }
-  .pill.proven { color:var(--ok); background:var(--ok-ghost); border-color:color-mix(in srgb,var(--ok) 30%,transparent); }
-  .pill.wip { color:var(--warn); background:var(--warn-ghost); border-color:color-mix(in srgb,var(--warn) 30%,transparent); }
-  .pill.gap { color:var(--bad); background:var(--bad-ghost); border-color:color-mix(in srgb,var(--bad) 30%,transparent); }
-  .pill.plan { color:var(--plan); background:var(--plan-ghost); border-color:color-mix(in srgb,var(--plan) 32%,transparent); }
-  /* sorry-free, but a deliberate repair of the paper's claim — deliberately not `proven` */
-  .pill.repaired { color:var(--rep); background:var(--rep-ghost); border-color:color-mix(in srgb,var(--rep) 32%,transparent); }
-
-  /* badge (bridge / guarded / subfolder / core) */
-  .badge {
-    display:inline-flex; align-items:center; gap:5px; font-family:var(--font-mono);
-    font-size:10.5px; font-weight:600; letter-spacing:.05em; text-transform:uppercase;
-    padding:2px 8px; border-radius:6px; border:1px solid var(--line); color:var(--muted);
-    background:var(--surface-2); white-space:nowrap;
-  }
-  .badge.bridge { color:var(--accent); border-color:color-mix(in srgb,var(--accent) 34%,transparent); background:var(--accent-ghost); }
-  .badge.guarded { color:var(--warn); border-color:color-mix(in srgb,var(--warn) 30%,transparent); background:var(--warn-ghost); }
-  .badge.core { color:var(--ok); border-color:color-mix(in srgb,var(--ok) 30%,transparent); background:var(--ok-ghost); }
-
-  /* ---------- the spine ---------- */
-  .zone { margin-bottom:8px; }
-  .zone-head {
-    display:flex; align-items:baseline; flex-wrap:wrap; gap:6px 14px;
-    padding:16px 0 10px; margin-left:64px;
-  }
-  .zone-head .zt { font-size:18px; font-weight:700; letter-spacing:-.01em; }
-  .zone-head .zref { font-family:var(--font-mono); font-size:12px; color:var(--muted); }
-  .zone-head .znote { flex-basis:100%; color:var(--ink-soft); font-size:13.5px; margin-left:0; }
-
-  .station { position:relative; padding:9px 0 9px 64px; }
-  /* the vertical rail */
-  .station::before {
-    content:""; position:absolute; left:23px; top:0; bottom:0; width:2px; background:var(--line);
-  }
-  .station.first::before { top:22px; }
-  .station.last::before { bottom:auto; height:22px; }
-  /* the node marker */
-  .node {
-    position:absolute; left:9px; top:14px; z-index:2;
-    width:30px; height:30px; border-radius:50%;
-    display:grid; place-items:center; font-family:var(--font-mono); font-weight:700; font-size:13px;
-    background:var(--surface); border:2px solid var(--accent); color:var(--accent);
-    box-shadow:0 0 0 4px var(--paper);
-  }
-  .station.bridge .node {
-    width:20px; height:20px; left:14px; top:19px; border-radius:5px; transform:rotate(45deg);
-    border-width:2px; border-color:var(--accent-2); background:var(--paper);
-  }
-  .station.bridge .node span{ transform:rotate(-45deg); font-size:0; }
-  .station.gap .node { border-color:var(--bad); color:var(--bad); }
-
-  .card {
-    background:var(--surface); border:1px solid var(--line); border-radius:14px;
-    padding:16px 18px; box-shadow:var(--shadow);
-    transition:transform .15s ease, box-shadow .15s ease, border-color .15s ease;
-  }
-  .card:hover { transform:translateY(-2px); box-shadow:0 4px 12px rgba(20,26,45,.10),0 18px 36px -18px rgba(20,26,45,.4); border-color:color-mix(in srgb,var(--accent) 30%,var(--line)); }
-  .station.gap .card { border-color:color-mix(in srgb,var(--bad) 40%,var(--line)); }
-  .station.bridge .card { background:linear-gradient(0deg,var(--surface),var(--surface)); border-style:dashed; }
-
-  .card-top { display:flex; align-items:flex-start; justify-content:space-between; gap:14px; flex-wrap:wrap; }
-  .card-title { font-size:16.5px; font-weight:700; letter-spacing:-.01em; line-height:1.25; }
-  .card-badges { display:flex; gap:6px; flex-wrap:wrap; align-items:center; }
-
-  .files { margin:9px 0 2px; display:flex; flex-direction:column; gap:2px; }
-  .fpath { font-family:var(--font-mono); font-size:12.5px; color:var(--ink-soft); word-break:break-all; }
-  .fpath .sub { color:var(--accent); }
-  .fpath .fn { color:var(--ink); font-weight:600; }
-
-  .metaline { display:flex; flex-wrap:wrap; gap:6px 18px; margin-top:11px; font-size:12.5px; color:var(--muted); font-family:var(--font-mono); }
-  .metaline b { color:var(--ink-soft); font-weight:600; }
-  .flow {
-    margin-top:11px; font-family:var(--font-mono); font-size:12.5px;
-    background:var(--surface-2); border:1px solid var(--line-soft); border-radius:8px;
-    padding:7px 11px; display:flex; align-items:center; gap:8px; flex-wrap:wrap; overflow-x:auto;
-  }
-  .flow .rel { color:var(--ink); font-weight:600; }
-  .flow .arrow { color:var(--accent); }
-  .desc { margin-top:11px; font-size:13.5px; color:var(--ink-soft); line-height:1.5; }
-  .desc b { color:var(--ink); font-weight:600; }
-
-  .iterband {
-    margin:0 0 2px 64px; font-family:var(--font-mono); font-size:11.5px; letter-spacing:.1em;
-    text-transform:uppercase; color:var(--muted); font-weight:600;
-  }
-
-  /* ---------- substrate grid ---------- */
-  .grid { display:grid; grid-template-columns:repeat(2,1fr); gap:14px; }
-  .sub-card {
-    background:var(--surface); border:1px solid var(--line); border-radius:14px; padding:17px 18px;
-    box-shadow:var(--shadow); display:flex; flex-direction:column; gap:9px;
-  }
-  .sub-card .sc-top { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; }
-  .sub-card .sc-name { font-weight:700; font-size:15.5px; letter-spacing:-.01em; }
-  .sub-card .sc-ref { font-family:var(--font-mono); font-size:11.5px; color:var(--muted); margin-top:2px; }
-  .sub-card .sc-files { font-family:var(--font-mono); font-size:12px; color:var(--ink-soft); word-break:break-all; }
-  .sub-card .sc-files .sub { color:var(--accent); }
-  .sub-card .sc-desc { font-size:13px; color:var(--ink-soft); line-height:1.5; }
-  .sub-card .sc-desc b{ color:var(--ink); font-weight:600; }
-  .assembly-head { margin-top:46px; }
-
-  /* ---------- gap explainer ---------- */
-  .grid.cols3 { grid-template-columns:repeat(3,1fr); }
-  .cheat {
-    margin-top:24px; background:var(--surface); border:1px solid color-mix(in srgb,var(--bad) 38%,var(--line));
-    border-radius:14px; box-shadow:var(--shadow); overflow:hidden;
-  }
-  .cheat .cheat-cap {
-    padding:13px 18px; border-bottom:1px solid var(--line-soft);
-    display:flex; gap:8px 14px; align-items:baseline; flex-wrap:wrap;
-  }
-  .cheat .cheat-cap b { font-size:14.5px; letter-spacing:-.01em; }
-  .cheat .cheat-cap .src { font-family:var(--font-mono); font-size:11.5px; color:var(--muted); }
-  .cheat pre {
-    margin:0; padding:15px 18px; overflow-x:auto; background:var(--surface-2);
-    font-family:var(--font-mono); font-size:12.8px; line-height:1.8; color:var(--ink-soft);
-  }
-  .cheat pre b { color:var(--ink); font-weight:600; }
-  .cheat pre .cm { color:var(--muted); }
-  .cheat pre .okm { color:var(--ok); font-weight:700; }
-  .cheat pre .badm { color:var(--bad); font-weight:700; }
-
-  /* ---------- index table ---------- */
-  .tablewrap { overflow-x:auto; border:1px solid var(--line); border-radius:14px; box-shadow:var(--shadow); background:var(--surface); }
-  table { border-collapse:collapse; width:100%; min-width:720px; font-size:13.5px; }
-  thead th {
-    text-align:left; font-family:var(--font-mono); font-size:10.5px; letter-spacing:.1em; text-transform:uppercase;
-    color:var(--muted); font-weight:600; padding:13px 14px; border-bottom:1px solid var(--line); white-space:nowrap;
-    background:var(--surface-2); position:sticky; top:0;
-  }
-  tbody td { padding:11px 14px; border-bottom:1px solid var(--line-soft); vertical-align:middle; }
-  tbody tr:last-child td { border-bottom:0; }
-  tbody tr:hover { background:var(--surface-2); }
-  td.path { font-family:var(--font-mono); font-size:12.5px; color:var(--ink); white-space:nowrap; }
-  td.path .sub { color:var(--accent); }
-  td.path .fn { font-weight:600; }
-  td.rolecell { font-family:var(--font-mono); font-size:12px; color:var(--muted); white-space:nowrap; }
-  td.refcell { font-family:var(--font-mono); font-size:12px; color:var(--ink-soft); white-space:nowrap; }
-  td.rowcell { font-family:var(--font-mono); font-weight:700; color:var(--ink-soft); text-align:center; }
-  td.sorrycell { font-family:var(--font-mono); text-align:right; color:var(--ink-soft); }
-  td.sorrycell.zero { color:var(--ok); }
-  td.sorrycell.hi { color:var(--warn); font-weight:700; }
-  .tfilter { display:flex; gap:8px; flex-wrap:wrap; margin-bottom:14px; }
-  .tfilter button {
-    font-family:var(--font-mono); font-size:12px; font-weight:600; letter-spacing:.03em;
-    padding:6px 13px; border-radius:999px; border:1px solid var(--line); background:var(--surface);
-    color:var(--ink-soft); cursor:pointer; transition:all .12s ease;
-  }
-  .tfilter button:hover { border-color:var(--accent); color:var(--accent); }
-  .tfilter button[aria-pressed="true"] { background:var(--accent); border-color:var(--accent); color:var(--on-accent); }
-
-  /* ---------- roadmap ---------- */
-  .roadmap { display:flex; flex-direction:column; gap:12px; }
-  .road-item {
-    display:flex; gap:14px; align-items:flex-start; background:var(--surface);
-    border:1px solid var(--line); border-left:3px solid var(--plan); border-radius:12px; padding:15px 18px; box-shadow:var(--shadow);
-  }
-  .road-item .ri-body h4 { margin:0 0 4px; font-size:15px; font-weight:700; letter-spacing:-.01em; }
-  .road-item .ri-body p { margin:0; font-size:13.5px; color:var(--ink-soft); line-height:1.5; }
-  .road-item .ri-body p code { color:var(--accent); font-size:12.5px; }
-  .road-item .ri-body a { color:var(--accent); font-weight:600; text-decoration-thickness:1px; text-underline-offset:2px; }
-  .road-item .ri-tag { flex:none; margin-top:2px; }
-
-  /* ---------- footer ---------- */
-  footer { border-top:1px solid var(--line); padding:36px 0 60px; margin-top:24px; color:var(--muted); font-size:13px; }
-  footer .refs { display:grid; grid-template-columns:repeat(2,1fr); gap:8px 28px; margin:16px 0 22px; }
-  footer .refs div { color:var(--ink-soft); font-size:13px; }
-  footer .refs .tag { font-family:var(--font-mono); color:var(--accent); font-weight:600; }
-  footer .foot-note { line-height:1.6; max-width:80ch; }
